{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table eggozdb.maplemonk.pp_box as SELECT CAST(TIMESTAMPADD(minute, 330, DATEADD(hour, 5.5, b.beat_date)) AS DATE) AS date, b.demand_classification AS area, CASE WHEN b.demand_classification IN ( \'Gurgaon-GT\',\'Delhi-GT\',\'NCR-OF-MT\',\'Noida-GT\',\'NCR-MT\',\'NCR-ON-MT\',\'NCR-HORECA\', \'Allahabad-GT\',\'Lucknow-GT\',\'UP-MT\',\'UP-ON-MT\',\'UP-OF-MT\', \'Indore-GT\',\'Bhopal-GT\',\'MP-ON-MT\',\'MP-OF-MT\', \'Chandigarh-GT\',\'Chandigarh-ON-MT\',\'Chandigarh-OF-MT\', \'Mumbai-ON-MT\',\'Jaipur-GT\',\'NCR-GT\',\'Punjab-ON-MT\',\'Jaipur-OF-MT\',\'Jaipur-ON-MT\' ) THEN \'NCR\' WHEN b.demand_classification IN ( \'Bangalore-Horeca\',\'Bangalore-MT\',\'Bangalore-GT\', \'Bangalore-ON-MT\',\'Bangalore-OF-MT\', \'Chennai-ON-MT\',\'Chennai-OF-MT\' ) THEN \'Bangalore\' WHEN b.demand_classification LIKE \'Hyderabad%\' THEN \'Hyderabad\' WHEN b.demand_classification LIKE \'Pune-ON-MT%\' THEN \'Hyderabad\' WHEN b.demand_classification IN ( \'East-MT\',\'East-ON-MT\',\'East-OF-MT\',\'Patna-GT\',\'Kolkata-GT\',\'D2C\' ) THEN \'NCR\' ELSE \'Others\' END AS \"Procurement region\", b.beat_number, b.beat_name, b.id, rrp.name, rrp.retailer_name, ww.name Loading_Point, SUM(PP_BOX_IN) AS PP_BOX_IN, SUM(PP_BOX_OUT) AS PP_BOX_OUT, SUM(CBB_BOX_IN) AS CBB_BOX_IN, SUM(CBB_BOX_OUT) AS CBB_BOX_OUT, MAX(qty.demand) AS demand, MAX(qty.out) AS out, MAX(qty.sold) AS sold, MAX(qty.promo) AS promo, MAX(qty.damage) AS damage, MAX(qty.old_damage) AS old_damage, MAX(qty.logistics_fresh_missing) AS logistics_fresh_missing, MAX(qty.logistics_old_missing) AS logistics_old_missing, MAX(qty.return) AS return, MAX(qty.supply) AS supply, MAX(qty.fresh_in) AS fresh_in, MAX(qty.transfer) AS transfer, MAX(qty.replacement) AS replacement, MAX(qty.old_in) AS old_in FROM eggozdb.maplemonk.my_sql_distributionchain_beatassignment b LEFT JOIN eggozdb.maplemonk.my_sql_warehouse_warehouse ww on ww.id = b.warehouse_id LEFT JOIN ( SELECT oo.beat_assignment_id,max(oo.retailer_name) retailer_name, MAX(rrp.name) name FROM eggozdb.maplemonk.my_sql_order_order oo LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON rr.id = oo.retailer_id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailerparent rrp ON rrp.id = rr.parent_id GROUP BY oo.beat_assignment_id, oo.retailer_name ) rrp ON rrp.beat_assignment_id = b.id LEFT JOIN ( SELECT s.beatassignment_id AS beatassignment_id, SUM(product_quantity * pp.sku_count) AS demand, SUM(product_out_quantity * pp.sku_count) AS out, SUM(product_sold_quantity * pp.sku_count) AS sold, SUM(product_promo_quantity * pp.sku_count) AS promo, SUM(product_damage_quantity * pp.sku_count) AS damage, SUM(product_old_damage_quantity * pp.sku_count) AS old_damage, SUM(product_logistics_fresh_missing_quantity* pp.sku_count) AS logistics_fresh_missing, SUM(product_logistics_old_missing_quantity* pp.sku_count) AS logistics_old_missing, SUM(product_return_quantity * pp.sku_count) AS return, SUM(product_supply_quantity * pp.sku_count) AS supply, SUM(product_fresh_in_quantity * pp.sku_count) AS fresh_in, SUM(product_transfer_quantity * pp.sku_count) AS transfer, SUM(product_replacement_quantity * pp.sku_count) AS replacement, SUM(product_return_replace_in_quantity * pp.sku_count) AS old_in FROM eggozdb.maplemonk.my_sql_saleschain_salesdemandsku s left join eggozdb.maplemonk.my_sql_product_product pp on pp.id = s.product_id GROUP BY s.beatassignment_id ) qty ON qty.beatassignment_id = b.id GROUP BY CAST(TIMESTAMPADD(minute, 330, DATEADD(hour, 5.5, b.beat_date)) AS DATE), b.demand_classification, b.beat_number, b.beat_name, b.id, rrp.name, qty.beatassignment_id,ww.name, rrp.retailer_name;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EGGOZDB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            